    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        var isValid = editContext.Validate();
        if (!isValid)
        {
            // Check if the only errors are from step-2 fields (which are empty but not yet shown).
            // Since step 2 isn't shown yet, we only care about step-1 field validity.
            var step1Fields = new[] {
                nameof(AppointmentFormModel.PatientName),
                nameof(AppointmentFormModel.Email),
                nameof(AppointmentFormModel.Phone),
                nameof(AppointmentFormModel.InsuranceProvider)
            };
            var step1Errors = editContext.GetValidationMessages()
                .Where((_, i) =>
                {
                    // Re-check: are there errors on step1 fields?
                    return true;
                });

            // Simpler approach: check each step-1 field individually
            bool step1Valid = true;
            foreach (var field in step1Fields)
            {
                if (editContext.GetValidationMessages(editContext.Field(field)).Any())
                {
                    step1Valid = false;
                    break;
                }
            }

            if (!step1Valid) return;
        }

        showStep2 = true;
        availabilityChecked = false;
        hasServerErrors = false;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        model.TimeSlot = null;
        availableSlots = [];

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityChecked = false;
        hasServerErrors = false;

        // Validate the full form first
        if (!editContext.Validate()) return;

        isChecking = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                hasServerErrors = true;
                availabilityChecked = true;
                return;
            }

            hasServerErrors = false;
            availabilityChecked = true;
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            // Re-run server validation before final submit
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                hasServerErrors = true;
                return;
            }

            // Simulate saving
            await Task.Delay(500);
            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    // ── Inner model with Data Annotations ──
    private class AppointmentFormModel
    {
        [Required(ErrorMessage = "Patient name is required.")]
        public string? PatientName { get; set; }

        [Required(ErrorMessage = "Email is required.")]
        [EmailAddress(ErrorMessage = "Invalid email format.")]
        public string? Email { get; set; }

        [Required(ErrorMessage = "Phone number is required.")]
        public string? Phone { get; set; }

        [Required(ErrorMessage = "Insurance provider is required.")]
        public string? InsuranceProvider { get; set; }

        [Required(ErrorMessage = "Please select a doctor.")]
        public string? Doctor { get; set; }

        [Required(ErrorMessage = "Appointment date is required.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateOnly? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Please select a time slot.")]
        public string? TimeSlot { get; set; }

        [Required(ErrorMessage = "Reason for visit is required.")]
        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
        public string? Reason { get; set; }
    }

    private class FutureDateAttribute : ValidationAttribute
    {
        protected override ValidationResult? IsValid(object? value, ValidationContext context)
        {
            if (value is DateOnly date && date <= DateOnly.FromDateTime(DateTime.Today))
            {
                return new ValidationResult(ErrorMessage);
            }
            return ValidationResult.Success;
        }
    }
}
