+            <label for="insurance" class="form-label">Insurance Provider</label>
+            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
+                <option value="">-- Select --</option>
+                <option value="Aetna">Aetna</option>
+                <option value="BlueCross">BlueCross</option>
+                <option value="Cigna">Cigna</option>
+                <option value="UnitedHealth">UnitedHealth</option>
+                <option value="None">None</option>
+            </InputSelect>
+            <ValidationMessage For="() => model.InsuranceProvider" />
+        </div>
+    </fieldset>
+
+    @if (!showStep2)
+    {
+        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
+            Next
+        </button>
+    }
+
+    @* ───── STEP 2: Appointment Details ───── *@
+    @if (showStep2)
+    {
+        <fieldset class="mt-4">
+            <legend>Appointment Details</legend>
+
+            <div class="mb-3">
+                <label for="doctor" class="form-label">Preferred Doctor</label>
+                <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
+                             @bind-Value:after="OnDoctorOrDateChanged">
+                    <option value="">-- Select --</option>
+                    @foreach (var doc in doctors)
+                    {
+                        <option value="@doc">@doc</option>
+                    }
+                </InputSelect>
+                <ValidationMessage For="() => model.Doctor" />
+            </div>
+
+            <div class="mb-3">
+                <label for="date" class="form-label">Appointment Date</label>
+                <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
+                           @bind-Value:after="OnDoctorOrDateChanged" />
+                <ValidationMessage For="() => model.AppointmentDate" />
+            </div>
+
+            <div class="mb-3">
+                <label for="timeslot" class="form-label">Time Slot</label>
+                <InputSelect id="timeslot" class="form-select" @bind-Value="model.TimeSlot">
+                    <option value="">-- Select --</option>
+                    @foreach (var slot in availableSlots)
+                    {
+                        <option value="@slot">@slot</option>
+                    }
+                </InputSelect>
+                <ValidationMessage For="() => model.TimeSlot" />
+            </div>
+
+            <div class="mb-3">
+                <label for="reason" class="form-label">Reason for Visit</label>
+                <InputTextArea id="reason" class="form-control" @bind-Value="model.Reason" rows="3" />
+                <ValidationMessage For="() => model.Reason" />
+            </div>
+        </fieldset>
+
+        <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
+            Back
+        </button>
+        <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability" disabled="@isChecking">
+            @(isChecking ? "Checking..." : "Check Availability")
+        </button>
+
+        @if (availabilityChecked && !hasServerErrors)
+        {
+            <button type="submit" class="btn btn-success" disabled="@isSubmitting">
+                @(isSubmitting ? "Booking..." : "Book Appointment")
+            </button>
+        }
+
+        @if (availabilityChecked && !hasServerErrors)
+        {
+            <div class="alert alert-success mt-3">Availability confirmed. You may submit your appointment.</div>
+        }
+    }
+
+    @if (submitted)
+    {
+        <div class="alert alert-success mt-3">
+            <strong>Appointment booked successfully!</strong>
+        </div>
+    }
+</EditForm>
+
+@code {
+    private AppointmentFormModel model = new();
+    private EditContext editContext = null!;
+    private CustomValidator? customValidator;
+
+    private List<string> doctors = [];
+    private List<string> availableSlots = [];
+
+    private bool showStep2;
+    private bool isChecking;
+    private bool isSubmitting;
+    private bool availabilityChecked;
+    private bool hasServerErrors;
+    private bool submitted;
+
+    protected override async Task OnInitializedAsync()
+    {
+        editContext = new EditContext(model);
+        doctors = await AppointmentService.GetDoctorsAsync();
+    }
+
+    private void ProceedToStep2()
+    {
+        // Validate only step-1 fields
+        var isValid = editContext.Validate();
+        if (!isValid)
+        {
+            // Check if the only errors are from step-2 fields (which are empty but not yet shown).
+            // Since step 2 isn't shown yet, we only care about step-1 field validity.
+            var step1Fields = new[] {
+                nameof(AppointmentFormModel.PatientName),
+                nameof(AppointmentFormModel.Email),
+                nameof(AppointmentFormModel.Phone),
+                nameof(AppointmentFormModel.InsuranceProvider)
+            };
+            var step1Errors = editContext.GetValidationMessages()
+                .Where((_, i) =>
+                {
+                    // Re-check: are there errors on step1 fields?
+                    return true;
+                });
+
+            // Simpler approach: check each step-1 field individually
+            bool step1Valid = true;
+            foreach (var field in step1Fields)
+            {
+                if (editContext.GetValidationMessages(editContext.Field(field)).Any())
+                {
+                    step1Valid = false;
+                    break;
+                }
+            }
+
+            if (!step1Valid) return;
+        }
+
+        showStep2 = true;
+        availabilityChecked = false;
+        hasServerErrors = false;
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        availabilityChecked = false;
+    }
+
+    private async Task OnDoctorOrDateChanged()
+    {
+        availabilityChecked = false;
+        model.TimeSlot = null;
+        availableSlots = [];
+
+        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
+        {
+            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
+                model.Doctor, model.AppointmentDate.Value);
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        customValidator?.ClearErrors();
+        availabilityChecked = false;
+        hasServerErrors = false;
+
+        // Validate the full form first
+        if (!editContext.Validate()) return;
+
+        isChecking = true;
+        try
+        {
+            var errors = await AppointmentService.ValidatePatientAsync(
+                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);
+
+            if (errors.Count > 0)
+            {
+                customValidator!.DisplayErrors(errors);
+                hasServerErrors = true;
+                availabilityChecked = true;
+                return;
+            }
+
+            hasServerErrors = false;
+            availabilityChecked = true;
+        }
+        finally
+        {
+            isChecking = false;
+        }
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        try
+        {
+            // Re-run server validation before final submit
+            var errors = await AppointmentService.ValidatePatientAsync(
+                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);
+
+            if (errors.Count > 0)
+            {
+                customValidator!.DisplayErrors(errors);
+                hasServerErrors = true;
+                return;
+            }
+
+            // Simulate saving
+            await Task.Delay(500);
+            submitted = true;
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    // ── Inner model with Data Annotations ──
+    private class AppointmentFormModel
+    {
+        [Required(ErrorMessage = "Patient name is required.")]
+        public string? PatientName { get; set; }
+
+        [Required(ErrorMessage = "Email is required.")]
+        [EmailAddress(ErrorMessage = "Invalid email format.")]
+        public string? Email { get; set; }
+
+        [Required(ErrorMessage = "Phone number is required.")]
+        public string? Phone { get; set; }
+
+        [Required(ErrorMessage = "Insurance provider is required.")]
+        public string? InsuranceProvider { get; set; }
+
+        [Required(ErrorMessage = "Please select a doctor.")]
+        public string? Doctor { get; set; }
+
+        [Required(ErrorMessage = "Appointment date is required.")]
+        [FutureDate(ErrorMessage = "Date must be in the future.")]
+        public DateOnly? AppointmentDate { get; set; }
+
+        [Required(ErrorMessage = "Please select a time slot.")]
+        public string? TimeSlot { get; set; }
+
+        [Required(ErrorMessage = "Reason for visit is required.")]
+        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
+        public string? Reason { get; set; }
+    }
+
+    private class FutureDateAttribute : ValidationAttribute
+    {
+        protected override ValidationResult? IsValid(object? value, ValidationContext context)
+        {
+            if (value is DateOnly date && date <= DateOnly.FromDateTime(DateTime.Today))
+            {
+                return new ValidationResult(ErrorMessage);
+            }
+            return ValidationResult.Success;
+        }
+    }
+}
